persuasion_principles:
{
  "Reciprocity": {"Explanation": "The email offers a warning about an attempted account login and asks the recipient to verify their account. This creates a sense of reciprocity, as the recipient feels like they are receiving something of value in return for their action."},
  "Scarcity": {"Explanation": "The email creates urgency by implying that the recipient has a limited time to act. If they do not verify their account within 12 hours, their account will be permanently closed. This creates a sense of scarcity."},
  "Authority": {"Explanation": "The email claims authority by referencing the Technical support team and stating that the email is subject to mandatory follow. This creates a sense of trust and credibility."},
  "Commitment/Consistency": {"Explanation": "The email references the recipient's previous behavior of not verifying their account. This creates a sense of commitment and consistency, which encourages the recipient to take action."},
  "Liking": {"Explanation": "The email uses familiarity and personalization by addressing the recipient by name and providing information about their account. This creates a sense of liking."},
  "Social proof": {"Explanation": "The email references other people's participation by stating that "someone else was trying to log into your Zimbra account." This creates a sense of social proof."}
}

